-- Wrap auth.uid() in RLS policy predicates in (SELECT ...) so Postgres evaluates it once
-- per statement (InitPlan) instead of once per row -- the Supabase-documented RLS perf
-- pattern. Predicate-equivalent (row visibility unchanged). Generated by
-- 'pgrls fix --rule PERF001' and verified (PERF001 -> 0). Refs #12.

-- [PERF001] Wrap auth function call(s) in policy 'Users can delete their own scouts' on public.scouts so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can delete their own scouts" ON public.scouts
    USING ((SELECT auth.uid()) = user_id);

-- [PERF001] Wrap auth function call(s) in policy 'Users can update their own scouts' on public.scouts so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can update their own scouts" ON public.scouts
    USING ((SELECT auth.uid()) = user_id);

-- [PERF001] Wrap auth function call(s) in policy 'Users can view their own scouts' on public.scouts so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Users can view their own scouts" ON public.scouts
    USING ((SELECT auth.uid()) = user_id);

